package com.aistock.prediction.portfolioanalysis;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import com.aistock.common.BusinessException;
import static com.aistock.prediction.portfolioanalysis.PortfolioRecords.*;import static com.aistock.prediction.portfolioanalysis.PortfolioTestEvidence.*;
class PortfolioSourceVerifierTest {
 final PortfolioSourceVerifier verifier=new PortfolioSourceVerifier();
 @Test void exactOwnedSourceAndCompleteSetAreRequired(){assertDoesNotThrow(()->verifier.verify(normal(),prices(),OWNER,DATE));assertThrows(BusinessException.class,()->verifier.verify(normal(),prices(),UUID.randomUUID(),DATE));assertThrows(BusinessException.class,()->verifier.verify(normal(),batch(quote("SH600030","25",DATE)),OWNER,DATE));assertThrows(BusinessException.class,()->verifier.verify(normal(),batch(quote("SH600030","25",DATE),quote("SH600030","25",DATE)),OWNER,DATE));assertThrows(BusinessException.class,()->verifier.verify(new PositionSnapshot(OWNER,"foreign","2",normal().items()),prices(),OWNER,DATE));}
 @Test void invalidDecimalsDatesVersionsAndDuplicatePositionsAreRejected(){for(String price:new String[]{"0","-1","1e2","NaN","1.0000001"})assertThrows(BusinessException.class,()->verifier.verify(snapshot(position("SH600030","1","1")),batch(quote("SH600030",price,DATE)),OWNER,DATE));assertThrows(BusinessException.class,()->verifier.verify(snapshot(position("SH600030","1","1")),batch(quote("SH600030","1",DATE.plusDays(1))),OWNER,DATE));assertThrows(BusinessException.class,()->verifier.verify(snapshot(position("SH600030","1","1"),position("SH600030","1","1")),prices(),OWNER,DATE));assertThrows(BusinessException.class,()->verifier.verify(snapshot(position("SH600030","1.0","1")),batch(quote("SH600030","1",DATE)),OWNER,DATE));}
 @Test void unavailableMustHaveReasonAndCannotContainInventedPrice(){var q=new Quote("SH600030","UNAVAILABLE",null,"0",null,null,null,"baostock","RAW","UNKNOWN",null,null,null,false);assertThrows(BusinessException.class,()->verifier.verify(snapshot(position("SH600030","1","1")),batch(q),OWNER,DATE));var wrong=new Quote("SH600030","AVAILABLE",null,"1",DATE,UUID.randomUUID(),"a".repeat(64),"tushare","QFQ","FRESH",null,null,null,false);assertThrows(BusinessException.class,()->verifier.verify(snapshot(position("SH600030","1","1")),batch(wrong),OWNER,DATE));}
}
